func TestESSyntaxStaticBindingLookup(t *testing.T) {
	runSyntaxTests(t, []rule_tester.ValidTestCase{
		{Code: "type String = string; new RegExp(String.raw`\\p{Script=Kawi}`, \"u\");",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "interface String {} new RegExp(String.raw`\\p{Script=Kawi}`, \"u\");",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "function f<String>() { new RegExp(String.raw`\\p{Script=Kawi}`, \"u\");}",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "function f(String: any) { new RegExp(String.raw`\\p{Script=Kawi}`, \"u\");}",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "const String = custom; new RegExp(String.raw`\\p{Script=Kawi}`, \"u\");",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "type String = string; String().isWellFormed(); type Array = number[]; Array().toSorted();",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "function f<Array, String>() { Array().toSorted(); String().isWellFormed(); }",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
		{Code: "type String = string; const Alias = String; new RegExp(Alias.raw`\\p{Script=Kawi}`, \"u\");",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"}},
	}, []rule_tester.InvalidTestCase{
		{Code: "const Alias = String; new RegExp(Alias.raw`\\p{Script=Kawi}`, \"u\");",
			FileName:        "scope.ts",
			Options:         []any{map[string]any{"version": "16"}},
			LanguageOptions: rule.LanguageOptions{SourceType: "module"},
			Errors:          []rule_tester.InvalidTestCaseError{{MessageId: "not-supported-yet", Message: "'regexp-unicode-property-escapes-2023' is not supported in Node.js. The configured version range is '16'.", Line: 1, Column: 23, EndLine: 1, EndColumn: 66}}},
	})
}
